'use strict';

// Server-owned deterministic eight-hour field, dealt on Grok's realm map (v1226, Phil 30 Oct 2026: "put this map in game. Swap out the
// old one" / "Make sure we remove all traces of the old map"). Land only - never the sea, never the World Tree island (the void).
// Region nodes are levels 1-6 (6 on the last 4 cells before the coast = "near the end of the region", Phil 3 Oct), wild nodes on the
// islets 7-10 (7 on islet land within 8 cells of a home region). Cells come from ../world-realm.js (GENERATED by tools/realm/build_realm.py).
const EPOCH_MS=8*3600000, COUNT=240, GRID_COLS=220, GRID_CELL=100/GRID_COLS;
const RESOURCES=['iron','crystal','silver','coal'];
const MAX_LEVEL=10;   // highest level field() deals (wild 7-10); assets/ui/world-mine-sync.js validates against the same number
const REALM=require('../world-realm.js');
const TERRAIN_BLOCKED=new Set(require('./world-terrain-blocked.json').cells);
const COAST_BAND=4, NEAR_REGION=8;   // 8 = the old wild corridor's region-edge band (20% of 40 cells)
const REGION_KEYS=['crystor','draymon','tefron','alumron'];
function epochAt(now){ return Math.floor(now/EPOCH_MS); }
function mineRand(seed){ let s=(seed>>>0)||1; return ()=>{ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }
function bfs(seed){   // cell distance (4-neighbour steps) from every seed cell
  const d=new Int16Array(GRID_COLS*GRID_COLS).fill(-1),q=[];
  for(let i=0;i<d.length;i++) if(seed(i%GRID_COLS,Math.floor(i/GRID_COLS))){d[i]=0;q.push(i);}
  for(let h=0;h<q.length;h++){const i=q[h],x=i%GRID_COLS,y=(i-x)/GRID_COLS;
    for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]) if(nx>=0&&ny>=0&&nx<GRID_COLS&&ny<GRID_COLS&&d[ny*GRID_COLS+nx]<0){d[ny*GRID_COLS+nx]=d[i]+1;q.push(ny*GRID_COLS+nx);}}
  return d;
}
let _cells=null;
function eligibleCells(){
  if(_cells) return _cells;
  const toSea=bfs((x,y)=>!REALM.isLand(x,y)), toRegion=bfs((x,y)=>REGION_KEYS.includes(REALM.landZone(x,y)));
  const out=[];
  for(let gy=2;gy<GRID_COLS-1;gy++) for(let gx=2;gx<GRID_COLS-1;gx++){
    const zone=REALM.landZone(gx,gy);
    if(!zone||zone==='worldtree'||TERRAIN_BLOCKED.has(gx+','+gy)) continue;
    out.push({gx,gy,zone,region:REGION_KEYS.includes(zone),coast:toSea[gy*GRID_COLS+gx],near:toRegion[gy*GRID_COLS+gx]});
  }
  return _cells=out;
}
function field(epoch){
  const cells=eligibleCells(),out=[],occupied=new Set(),rnd=mineRand((epoch*2654435761)>>>0); let guard=0;
  while(out.length<COUNT&&guard++<COUNT*12){
    const c=cells[Math.floor(rnd()*cells.length)], square=c.gx+','+c.gy;
    if(occupied.has(square)) continue;
    occupied.add(square);
    let level; const r=rnd();
    if(c.region) level=c.coast<=COAST_BAND?6:(r<0.30?1:r<0.55?2:r<0.75?3:r<0.90?4:5);
    else level=c.near<=NEAR_REGION?7:(r<0.4?8:r<0.75?9:10);
    const res=RESOURCES[Math.floor(rnd()*RESOURCES.length)];
    out.push({id:'mn'+epoch+'_'+out.length,res,level,gx:c.gx,gy:c.gy,x:c.gx*GRID_CELL,y:c.gy*GRID_CELL,region:c.zone});
  }
  return out;
}
function nodeById(id,now){
  const ep=epochAt(now), prefix='mn'+ep+'_';
  if(typeof id!=='string'||!id.startsWith(prefix)) return null;
  const index=Number(id.slice(prefix.length));
  if(!Number.isInteger(index)||index<0||index>=COUNT||id!==prefix+index) return null;
  return field(ep)[index]||null;
}
module.exports={EPOCH_MS,COUNT,GRID_COLS,GRID_CELL,RESOURCES,MAX_LEVEL,epochAt,mineRand,field,nodeById};
